messages.content:
Tool response:
Tool: bulk_update_unreconciled_gifts
Description: Update all unreconciled gifts logged between October 1–15, 2024, that currently have no campaign or fund assigned, to default to Campaign 'Year-End Appeal 2024' and Fund 'Unrestricted Gifts'.
Parameters:
    {
      "type": "object",
      "properties": {
        "start_date": {
          "type": "string",
          "description": "Start date for filtering gifts (YYYY-MM-DD)",
          "title": "Start Date"
        },
        "end_date": {
          "type": "string",
          "description": "End date for filtering gifts (YYYY-MM-DD)",
          "title": "End Date"
        },
        "campaign_name": {
          "type": "string",
          "description": "Name of the campaign to assign",
          "title": "Campaign Name"
        },
        "fund_name": {
          "type": "string",
          "description": "Name of the fund to assign",
          "title": "Fund Name"
        }
      },
      "required": [
        "start_date",
        "end_date",
        "campaign_name",
        "fund_name"
      ]
    }
